INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "王重盈加兼中书令", "start_year": 891, "end_year": 891, "time_original": "891年九月条；具体日未载", "dynasty": "唐", "description": "朝廷加护国节度使王重盈兼中书令。", "phases": [], "location_name": "护国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f2a4da15-8ac6-5aa7-900c-882fb3884a8d"}, {"title": "顾彦朗去世，军推顾彦晖知留后", "start_year": 891, "end_year": 891, "time_original": "891年九月条；具体日未载", "dynasty": "唐", "description": "东川节度使顾彦朗去世，军中推其弟顾彦晖知留后。", "phases": [], "location_name": "东川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b2930fb1-bc3e-5e5b-b3b9-ccdd6de97716"}, {"title": "宿州张筠投降丁会", "start_year": 891, "end_year": 891, "time_original": "891年十月壬午", "dynasty": "唐", "description": "宿州刺史张筠投降丁会。", "phases": [], "location_name": "宿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b823f227-d49f-541b-89a1-dd254873f9a4"}, {"title": "王建获朝廷任西川节度使", "start_year": 891, "end_year": 891, "time_original": "891年十月癸未", "dynasty": "唐", "description": "朝廷以永平节度使王建为西川节度使。", "phases": [], "location_name": "永平、西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1c50a1a1-8dac-56bc-96d4-975c02396f88"}, {"title": "朝廷废永平军", "start_year": 891, "end_year": 891, "time_original": "891年十月甲申", "dynasty": "唐", "description": "朝廷废永平军。", "phases": [], "location_name": "永平", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b52d2699-3f80-5921-a333-34df28defce5"}, {"title": "通鉴评王建得西川后的政事与忌杀", "start_year": null, "end_year": null, "time_original": "得西川后；各行为确年日未载", "dynasty": "唐", "description": "《通鉴》述王建得西川后留心政事、容纳直言、好施乐士、用人尽才且谦恭俭素，又称多忌好杀，功名诸将多因事被诛。", "phases": [], "location_name": "西川", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c2d67612-5afc-5ab8-82a6-ab52609f63e2"}, {"title": "杨复恭与杨守信被告谋反", "start_year": 891, "end_year": 891, "time_original": "891年十月乙酉前", "dynasty": "唐", "description": "杨复恭住所近玉山营，假子杨守信任玉山军使、屡来探望。有人告杨复恭与守信谋反。", "phases": [], "location_name": "京师、玉山营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "22042bb5-1a77-5402-bdb8-7597b0f9430b"}, {"title": "李顺节李守节攻杨复恭宅未克", "start_year": 891, "end_year": 891, "time_original": "891年十月乙酉", "dynasty": "唐", "description": "皇帝御安喜门陈兵自卫，命李顺节与李守节率兵攻杨复恭宅。张绾率家众拒战，杨守信引兵助，李顺节等未能攻克。", "phases": [], "location_name": "安喜门、杨复恭宅", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "0b8ae891-bf2f-5b58-a7d5-c966da42011e"}, {"title": "刘崇望止禁兵掠市，引其东击", "start_year": 891, "end_year": 891, "time_original": "891年十月丙戌", "dynasty": "唐", "description": "禁兵守含光门待开欲掠两市，刘崇望劝其应到皇帝督战处杀敌立功、勿贪小利，士卒遵从而东；杨守信军望兵遂溃。", "phases": [], "location_name": "含光门、街东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "832a0d80-f1de-5625-8873-6275f31617cb"}, {"title": "杨复恭杨守信奔兴元，权安追斩张绾", "start_year": 891, "end_year": 891, "time_original": "891年十月丙戌后条", "dynasty": "唐", "description": "杨守信与杨复恭携族由通化门出逃向兴元，永安都头权安追击，擒张绾并斩之。", "phases": [], "location_name": "通化门、兴元", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "be8d9f2a-272c-58d0-a8cd-d981c46f1d00"}, {"title": "杨守亮等兴元举兵拒朝廷", "start_year": 891, "end_year": 891, "time_original": "891年十月条；杨复恭至兴元后", "dynasty": "唐", "description": "杨复恭至兴元后，杨守亮、杨守忠、杨守贞及绵州刺史杨守厚同举兵拒朝廷，以讨李顺节为名。", "phases": [], "location_name": "兴元、绵州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "41476021-580d-5fa3-aa45-cbc9822351a6"}, {"title": "李克用龙尾岗破镇兵取临城", "start_year": 891, "end_year": 891, "time_original": "891年十月条；具体日未载", "dynasty": "唐", "description": "李克用攻击王镕，在龙尾岗大败镇兵，书载斩获万计，攻取临城，再攻元氏、柏乡。", "phases": [], "location_name": "龙尾岗、临城、元氏、柏乡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1f6aa062-2b23-574c-9ef7-948f1680f2c6"}, {"title": "李匡威引幽兵救镇，李克用掠还邢州", "start_year": 891, "end_year": 891, "time_original": "891年十月条；龙尾岗战后", "dynasty": "唐", "description": "李匡威引幽州兵援救王镕，李克用大掠而还，驻邢州。", "phases": [], "location_name": "幽州、邢州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7aa35ed8-3a8f-5278-adca-1c78c04acac6"}, {"title": "郭铢杀曹州郭词降朱全忠", "start_year": 891, "end_year": 891, "time_original": "891年十一月", "dynasty": "唐", "description": "曹州都将郭铢杀刺史郭词，投降朱全忠。", "phases": [], "location_name": "曹州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e1f723ee-38e8-5e1a-b1d4-6157e07f2ab0"}, {"title": "朱瑾率万余人攻单州", "start_year": 891, "end_year": 891, "time_original": "891年十一月条；具体日未载", "dynasty": "唐", "description": "泰宁节度使朱瑾率万余人攻击单州。", "phases": [], "location_name": "单州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fb8ed9ce-dcb1-5d60-8e31-1ffce4a34f2f"}, {"title": "刘知俊率二千人降朱全忠并获任", "start_year": 891, "end_year": 891, "time_original": "891年十一月乙丑", "dynasty": "唐", "description": "时溥将刘知俊率二千人降朱全忠，《通鉴》称此后时溥军不振；朱全忠以刘知俊为左右开道指挥使。", "phases": [], "location_name": "徐州、汴", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bc2b8d0d-0bc6-58dd-b2e0-cccfc558b8ac"}, {"title": "刘弘鄂因恶孙儒举寿州降朱全忠", "start_year": 891, "end_year": 891, "time_original": "891年十一月辛未", "dynasty": "唐", "description": "寿州将刘弘鄂厌恶孙儒残暴，举州投降朱全忠。", "phases": [], "location_name": "寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c3a80ef1-87c3-5eb8-ae4c-34bd5c29fe9e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

